<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\TemplateAsset\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;

use OpenApi\Attributes as OA;
use Throwable;

use Civi\Lughauth\Features\Document\TemplateAsset\Domain\TemplateAssetRef;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Usecase\Create\TemplateAssetCreateUsecase;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Usecase\List\TemplateAssetListUsecase;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Usecase\Update\TemplateAssetUpdateUsecase;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Usecase\Delete\TemplateAssetDeleteUsecase;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Usecase\Retrieve\TemplateAssetRetrieveUsecase;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Usecase\Enable\TemplateAssetEnableUsecase;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Usecase\Disable\TemplateAssetDisableUsecase;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class TemplateAssetAllowController
{
  use LoggerAwareTrait;
  use TracerAwareTrait;

  public function __construct(
    private readonly TemplateAssetCreateUsecase $createUsecase,
    private readonly TemplateAssetListUsecase $listUsecase,
    private readonly TemplateAssetUpdateUsecase $updateUsecase,
    private readonly TemplateAssetDeleteUsecase $deleteUsecase,
    private readonly TemplateAssetRetrieveUsecase $retrieveUsecase,
    private readonly TemplateAssetEnableUsecase $enableUsecase,
    private readonly TemplateAssetDisableUsecase $disableUsecase,
  ) {
  }
  #[OA\Get(path: "/api/me/acl/document/template-asset", tags: ["Template asset access control"], description:"Allows",
    responses: [
      new OA\Response(response: 200, description: "Ok"),
    ])
  ]
  public function genericAllow(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
  {
    $this->logDebug("Check generic allow for Template asset");
    $span = $this->startSpan("Generic allow for Template asset");
    try {
      $value = [
        'allows' => [
          $this->createUsecase->allowCreate(),
          $this->listUsecase->allowList(),
          $this->updateUsecase->allowUpdate(),
        $this->deleteUsecase->allowDelete(),
        $this->retrieveUsecase->allowRetrieve(),
        $this->enableUsecase->allowEnable(),
        $this->disableUsecase->allowDisable(),
        ],
        'fields' => [
          'noEditables' => $this->updateUsecase->fixedFields(),
          'noVisibles' => $this->retrieveUsecase->hiddenFields()
        ]
      ];
      $encoded = json_encode($value);
      $response->getBody()->write($encoded === false ? '' : $encoded);
      return $response->withStatus(200)
            ->withHeader('Content-Type', 'application/json');
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  #[OA\Get(path: "/api/me/acl/document/template-asset/{uid}", tags: ["Template asset access control"], description:"Allows",
    parameters: [
      new OA\PathParameter(name: "uid", required: true, schema: new OA\Schema(type: "string")),
    ],
    responses: [
      new OA\Response(response: 200, description: "Ok"),
      new OA\Response(response: 404, description: "Not found"),
    ])
  ]
  public function contextualAllow(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
  {
    $this->logDebug("Check specific allow for Template asset");
    $span = $this->startSpan("Specific allow for Template asset");
    try {
      if (!isset($args['uid'])) {
        throw new NotFoundException('-');
      }
      $ref = new TemplateAssetRef( uid: $args['uid'] );
      $value = [
        'allows' => [
          $this->updateUsecase->allowUpdate($ref),
        $this->deleteUsecase->allowDelete($ref),
        $this->retrieveUsecase->allowRetrieve($ref),
        $this->enableUsecase->allowEnable($ref),
        $this->disableUsecase->allowDisable($ref),
        ],
        'fields' => [
          'noEditables' => $this->updateUsecase->fixedFields($ref),
          'noVisibles' => $this->retrieveUsecase->hiddenFields($ref)
        ]
      ];
      $encoded = json_encode($value);
      $response->getBody()->write($encoded === false ? '' : $encoded);
      return $response->withStatus(200)
            ->withHeader('Content-Type', 'application/json');
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
}
